#import "WBSessionInternal.h"
@implementation WBSession (History)
- (void)addValues:(NSArray *)values metric:(NSString *)m date:(NSString *)date interval:(double)interval to:(NSMutableArray *)records {
    [records addObjectsFromArray:[WBPolicy indexedValues:values metric:m date:date interval:interval]];
}
- (void)readDay:(NSString *)m day:(NSInteger)day date:(NSString *)date done:(WBReply)done {
    if(day<0 || day>6){done(nil,WBError(@"INVALID_ARGUMENT",@"Frozen date outside device retention"));return;}
    NSString *s=[self metricCapability:m][@"history"][@"support"];if(![s isEqual:@"supported"]){done(nil,WBError([s isEqual:@"unknown"]?@"CAPABILITY_UNKNOWN":@"UNSUPPORTED",@"History support unavailable"));return;}
    WBReply reply=[self once:done];NSMutableArray *records=[NSMutableArray new];
    void(^ok)(void)=^{reply(@{@"records":records},nil);};void(^fail)(void)=^{reply(nil,WBError(@"SDK_ERROR",@"History read failed"));};
    if([m isEqual:@"heartRate"]) [QCSDKCmdCreator getSchedualHeartRateDataWithDayIndexs:@[@(day)] success:^(NSArray<QCSchedualHeartRateModel *> *models){for(QCSchedualHeartRateModel *model in models)[self addValues:model.heartRates metric:m date:model.date?:date interval:model.secondInterval/60.0 to:records];ok();} fail:fail];
    else if([m isEqual:@"bloodOxygen"]) [QCSDKCmdCreator getBloodOxygenDataWithIntervalByDayIndex:day finished:^(NSInteger interval,NSArray *values,NSError *error){if(error){fail();return;}if(values.count && [values.firstObject isKindOfClass:QCBloodOxygenModel.class]) {for(QCBloodOxygenModel *v in values){if(v.soa2<=0)continue;NSMutableDictionary *r=[@{@"metric":m,@"date":date,@"source":v.sourceType==1?@"manual":@"scheduled",@"value":@(v.soa2),@"unit":@"%"} mutableCopy];if(v.date) {r[@"timestamp"]=@(v.date.timeIntervalSince1970*1000);r[@"utcOffsetMinutes"]=@([NSTimeZone.localTimeZone secondsFromGMTForDate:v.date]/60);}[records addObject:r];}}else [self addValues:values metric:m date:date interval:interval to:records];ok();}];
    else if([m isEqual:@"temperature"]) [QCSDKCmdCreator getSchedualTemperatureDataByDayIndex:day finished:^(NSArray *values,NSError *error){if(error){fail();return;}for(QCTemperatureModel *v in values){if(![v isKindOfClass:QCTemperatureModel.class] || !isfinite(v.temperature) || v.temperature<=0)continue;NSMutableDictionary *r=[@{@"metric":m,@"date":date,@"source":@"scheduled",@"value":@(v.temperature),@"unit":@"celsius"} mutableCopy];if(v.time){r[@"timestamp"]=@(v.time.timeIntervalSince1970*1000);r[@"utcOffsetMinutes"]=@([NSTimeZone.localTimeZone secondsFromGMTForDate:v.time]/60);}[records addObject:r];}ok();}];
    else if([m isEqual:@"hrv"]) [QCSDKCmdCreator getHRVSamplesWithDayIndexes:@[@(day)] finished:^(NSArray<QCHRVDayModel *> *values,NSError *error){if(error){fail();return;}for(QCHRVDayModel *model in values)for(QCHRVSampleModel *sample in model.samples){if(sample.value<=0)continue;NSMutableDictionary *r=[@{@"metric":m,@"date":model.date?:date,@"source":@"scheduled",@"value":@(sample.value),@"unit":@"vendor",@"intervalMinutes":@(model.intervalMinutes)} mutableCopy];if(sample.time){r[@"timestamp"]=@(sample.time.timeIntervalSince1970*1000);r[@"utcOffsetMinutes"]=@([NSTimeZone.localTimeZone secondsFromGMTForDate:sample.time]/60);}[records addObject:r];}ok();}];
    else if([m isEqual:@"stress"]) [QCSDKCmdCreator getOtherDataPressureWithDayIndexes:@[@(day)] finished:^(NSArray<QCOtherDataPressureModel *> *values,NSError *error){if(error){fail();return;}for(QCOtherDataPressureModel *v in values)[self addValues:v.values metric:m date:date interval:v.interval to:records];ok();}];
    else if([m isEqual:@"steps"]) [QCSDKCmdCreator getOneDaySportBy:day success:^(QCSportModel *v){if(v)[records addObject:@{@"metric":m,@"date":date,@"source":@"scheduled",@"steps":@(v.totalStepCount),@"distanceMeters":@(v.distance)}];ok();} fail:fail];
    else [QCSDKCmdCreator getFulldaySleepDetailDataByDay:day sleepDatas:^(NSArray<QCSleepModel *> *night,NSArray<QCSleepModel *> *naps){for(QCSleepModel *v in [night arrayByAddingObjectsFromArray:naps?:@[]]){
        NSMutableArray *phases=[NSMutableArray new];NSArray *types=[v.dataTypes componentsSeparatedByString:@","],*minutes=[v.dataMinutes componentsSeparatedByString:@","];
        if(v.dataTypes.length && types.count==minutes.count){for(NSUInteger i=0;i<types.count;i++)if([minutes[i] integerValue]>0)[phases addObject:@{@"stage":@"unknown",@"vendorStage":@([types[i] integerValue]),@"durationSeconds":@([minutes[i] integerValue]*60)}];}
        else {NSString *stage=@{@(SLEEPTYPESOBER):@"awake",@(SLEEPTYPELIGHT):@"light",@(SLEEPTYPEDEEP):@"deep",@(SLEEPTYPEREM):@"rem"}[@(v.type)]?:@"unknown";if(v.total>0)[phases addObject:@{@"stage":stage,@"vendorStage":@(v.type),@"durationSeconds":@(v.total*60)}];}
        [records addObject:@{@"metric":m,@"date":date,@"source":@"scheduled",@"startLocal":v.happenDate?:@"",@"endLocal":v.endTime?:@"",@"nap":@(v.isMidday),@"durationSeconds":@(MAX(0,v.total)*60),@"phases":phases}];}ok();} fail:fail];
}
- (void)history:(NSArray<NSString *> *)metrics start:(NSInteger)start days:(NSInteger)days {
    NSCalendar *calendar=[NSCalendar.currentCalendar copy];NSDate *anchor=NSDate.date;NSDateFormatter *format=[NSDateFormatter new];format.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US_POSIX"];format.calendar=calendar;format.timeZone=calendar.timeZone;format.dateFormat=@"yyyy-MM-dd";
    NSMutableArray *jobs=[NSMutableArray new];for(NSString *m in metrics)for(NSInteger i=start;i<start+days;i++)[jobs addObject:@{@"metric":m,@"day":@(i),@"date":[format stringFromDate:[calendar dateByAddingUnit:NSCalendarUnitDay value:-i toDate:anchor options:0]]}];
    NSMutableArray *batches=[NSMutableArray new];NSString *token=self.gate.token,*device=self.peripheral.identifier.UUIDString;self.historyFailure=^NSDictionary *(NSDictionary *e){return [WBPolicy failedHistory:jobs batches:batches operation:token device:device error:e];};__weak WBSession *weak=self;
    self.historyNext=^(NSUInteger index){WBSession *s=weak;if(![s.gate isCurrent:token]){s.historyNext=nil;return;}if(index==jobs.count){NSUInteger errors=0;for(NSDictionary *b in batches)if([b[@"status"] isEqual:@"error"])errors++;[s complete:@{@"operationId":token,@"deviceId":device,@"status":errors==0?@"success":errors==batches.count?@"failed":@"partial",@"batches":batches} error:nil];s.historyNext=nil;return;}
        NSDictionary *job=jobs[index];
        NSDate *target=[format dateFromString:job[@"date"]];
        NSInteger adjusted=[WBPolicy dayIndex:target today:NSDate.date calendar:calendar];
        [s readDay:job[@"metric"] day:adjusted date:job[@"date"] done:^(NSDictionary *result,NSDictionary *error){NSMutableDictionary *b=[@{@"operationId":token,@"deviceId":device,@"batchIndex":@(index),@"metric":job[@"metric"],@"date":job[@"date"],@"status":error?@"error":@"success",@"records":result[@"records"]?:@[]} mutableCopy];if(error)b[@"error"]=error;[batches addObject:b];[s emit:@"historyBatch" data:b];[s emit:@"syncProgress" data:@{@"operationId":token,@"deviceId":device,@"completed":@(index+1),@"total":@(jobs.count)}];if(s.historyNext)s.historyNext(index+1);}];
    };self.historyNext(0);
}
@end
